import React from "react"
import { useDroppable } from "@dnd-kit/core"
import { format, isToday, isSameDay } from "date-fns"
import { buildCalendarWeeks, formatMonthYear, toDateKey } from "../../../utils/dateUtils"
import { Appointment, AppointmentStatus } from "../../../hooks/useAppointments"
import AppointmentChip from "./AppointmentChip"

const STATUS_COLORS: Record<AppointmentStatus, string> = {
  scheduled: "bg-blue-100 text-blue-800",
  confirmed: "bg-green-100 text-green-800",
  "pending-approval": "bg-yellow-100 text-yellow-800",
  "in-progress": "bg-orange-100 text-orange-800",
  completed: "bg-gray-100 text-gray-600",
  cancelled: "bg-red-100 text-red-400 line-through",
}

const WEEK_DAYS = ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"]

interface CalendarGridProps {
  year: number
  month: number
  appointments: Appointment[]
  selectedDate: Date | null
  onDayClick: (date: Date) => void
  onMonthChange: (year: number, month: number) => void
}

interface DroppableDayProps {
  date: Date
  isCurrentMonth: boolean
  appointments: Appointment[]
  isSelected: boolean
  onDayClick: (date: Date) => void
}

function DroppableDay({
  date,
  isCurrentMonth,
  appointments,
  isSelected,
  onDayClick,
}: DroppableDayProps) {
  const id = toDateKey(date)
  const { isOver, setNodeRef } = useDroppable({ id, disabled: !isCurrentMonth })

  const today = isToday(date)
  const visible = appointments.slice(0, 3)
  const overflow = appointments.length - 3

  return (
    <div
      ref={setNodeRef}
      onClick={() => isCurrentMonth && onDayClick(date)}
      className={`min-h-[90px] p-1.5 border-b border-r border-gray-100 flex flex-col transition-colors ${
        !isCurrentMonth
          ? "bg-gray-50 cursor-default"
          : isOver
          ? "bg-blue-50 cursor-pointer"
          : isSelected
          ? "bg-blue-50 cursor-pointer"
          : "bg-white hover:bg-gray-50 cursor-pointer"
      }`}
    >
      <span
        className={`text-xs font-medium mb-1 w-6 h-6 flex items-center justify-center rounded-full ${
          !isCurrentMonth
            ? "text-gray-300"
            : today
            ? "bg-blue-600 text-white"
            : isSelected
            ? "text-blue-600 font-bold"
            : "text-gray-700"
        }`}
      >
        {format(date, "d")}
      </span>

      <div className="flex flex-col gap-0.5 flex-1">
        {visible.map(appt => (
          <AppointmentChip
            key={appt.id}
            appointment={appt}
            statusColors={STATUS_COLORS}
          />
        ))}
        {overflow > 0 && (
          <span className="text-xs text-gray-400 px-1">+{overflow} more</span>
        )}
      </div>
    </div>
  )
}

export default function CalendarGrid({
  year,
  month,
  appointments,
  selectedDate,
  onDayClick,
  onMonthChange,
}: CalendarGridProps) {
  const weeks = buildCalendarWeeks(year, month)
  const currentMonthDate = new Date(year, month, 1)

  function handlePrev() {
    const d = new Date(year, month - 1, 1)
    onMonthChange(d.getFullYear(), d.getMonth())
  }

  function handleNext() {
    const d = new Date(year, month + 1, 1)
    onMonthChange(d.getFullYear(), d.getMonth())
  }

  // Group appointments by date key for fast lookup
  const apptsByDay = appointments.reduce<Record<string, Appointment[]>>((acc, appt) => {
    const key = toDateKey(appt.date)
    if (!acc[key]) acc[key] = []
    acc[key].push(appt)
    return acc
  }, {})

  // Sort each day's appointments by timeSlot
  Object.values(apptsByDay).forEach(list =>
    list.sort((a, b) => a.timeSlot.localeCompare(b.timeSlot))
  )

  return (
    <div className="bg-white rounded-xl shadow-sm overflow-hidden">
      {/* Month header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-gray-100">
        <button
          onClick={handlePrev}
          className="p-1.5 rounded-lg hover:bg-gray-100 text-gray-600 transition-colors"
          aria-label="Previous month"
        >
          ‹
        </button>
        <h2 className="font-semibold text-gray-800 text-sm">
          {formatMonthYear(currentMonthDate)}
        </h2>
        <button
          onClick={handleNext}
          className="p-1.5 rounded-lg hover:bg-gray-100 text-gray-600 transition-colors"
          aria-label="Next month"
        >
          ›
        </button>
      </div>

      {/* Day-of-week headers */}
      <div className="grid grid-cols-7 border-b border-gray-100">
        {WEEK_DAYS.map(day => (
          <div
            key={day}
            className="text-center text-xs font-medium text-gray-500 py-2 border-r border-gray-100 last:border-r-0"
          >
            {day}
          </div>
        ))}
      </div>

      {/* Calendar grid */}
      <div className="grid grid-cols-7">
        {weeks.flat().map(({ date, isCurrentMonth }) => {
          const key = toDateKey(date)
          const dayAppts = apptsByDay[key] ?? []
          const isSelected = selectedDate ? isSameDay(date, selectedDate) : false

          return (
            <DroppableDay
              key={key}
              date={date}
              isCurrentMonth={isCurrentMonth}
              appointments={dayAppts}
              isSelected={isSelected}
              onDayClick={onDayClick}
            />
          )
        })}
      </div>
    </div>
  )
}

export { STATUS_COLORS }
