import React, { useEffect, useState } from "react"
import { Appointment, AppointmentStatus } from "../../../hooks/useAppointments"
import { formatDayHeader } from "../../../utils/dateUtils"
import { STATUS_COLORS } from "./CalendarGrid"
import AppointmentWizard from "../Appointments/AppointmentWizard"

interface DayPanelProps {
  date: Date | null
  appointments: Appointment[]
  onClose: () => void
}

const STATUS_LABELS: Record<AppointmentStatus, string> = {
  scheduled: "Scheduled",
  confirmed: "Confirmed",
  "pending-approval": "Pending",
  "in-progress": "In Progress",
  completed: "Completed",
  cancelled: "Cancelled",
}

export default function DayPanel({ date, appointments, onClose }: DayPanelProps) {
  const isOpen = date !== null
  const [showWizard, setShowWizard] = useState(false)

  // Reset wizard when panel closes or date changes
  useEffect(() => {
    setShowWizard(false)
  }, [date])

  // Close on Escape (only when wizard is not open — wizard handles its own cancel)
  useEffect(() => {
    function onKey(e: KeyboardEvent) {
      if (e.key === "Escape" && !showWizard) onClose()
    }
    if (isOpen) document.addEventListener("keydown", onKey)
    return () => document.removeEventListener("keydown", onKey)
  }, [isOpen, onClose, showWizard])

  const sorted = [...appointments].sort((a, b) =>
    a.timeSlot.localeCompare(b.timeSlot)
  )

  return (
    <>
      {/* Mobile overlay — closes panel (not wizard) */}
      {isOpen && !showWizard && (
        <div
          className="fixed inset-0 bg-black/40 z-30 md:hidden"
          onClick={onClose}
        />
      )}

      {/* Panel */}
      <div
        className={`fixed top-0 right-0 h-full z-40 flex flex-col bg-white shadow-xl transition-transform duration-300 ease-in-out
          w-full md:w-[380px]
          ${isOpen ? "translate-x-0" : "translate-x-full"}`}
      >
        {/* Header */}
        <div className="flex items-center justify-between px-5 py-4 border-b border-gray-100 flex-shrink-0">
          <h2 className="font-semibold text-gray-800 text-sm">
            {date ? formatDayHeader(date) : ""}
          </h2>
          <button
            onClick={onClose}
            className="text-gray-400 hover:text-gray-700 text-xl leading-none transition-colors"
            aria-label="Close panel"
          >
            ✕
          </button>
        </div>

        {/* Content */}
        <div className="flex-1 overflow-y-auto px-5 py-4">
          {showWizard && date ? (
            <AppointmentWizard
              date={date}
              onDone={() => setShowWizard(false)}
              onCancel={() => setShowWizard(false)}
            />
          ) : sorted.length === 0 ? (
            <div className="flex flex-col items-center justify-center h-full gap-4 text-center">
              <p className="text-gray-400 text-sm">No appointments for this day</p>
              <button
                onClick={() => setShowWizard(true)}
                className="px-4 py-2 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
              >
                + Add Appointment
              </button>
            </div>
          ) : (
            <div className="flex flex-col gap-3">
              {sorted.map(appt => (
                <div
                  key={appt.id}
                  className="flex items-start gap-3 p-3 rounded-lg border border-gray-100 hover:border-gray-200 bg-white transition-colors"
                >
                  <span className="text-xs font-mono text-gray-500 mt-0.5 flex-shrink-0 w-12">
                    {appt.timeSlot}
                  </span>
                  <div className="flex-1 min-w-0">
                    <p className="text-sm font-medium text-gray-800 truncate">
                      {appt.clientName}
                    </p>
                    <p className="text-xs text-gray-500 truncate">{appt.serviceType}</p>
                  </div>
                  <div className="flex items-center gap-2 flex-shrink-0">
                    <span
                      className={`text-xs px-2 py-0.5 rounded-full font-medium ${
                        STATUS_COLORS[appt.status]
                      }`}
                    >
                      {STATUS_LABELS[appt.status]}
                    </span>
                    <button
                      className="text-xs text-gray-400 hover:text-blue-600 transition-colors"
                      title="Edit (Phase 03)"
                      disabled
                    >
                      ✎
                    </button>
                  </div>
                </div>
              ))}
            </div>
          )}
        </div>

        {/* Footer — hidden while wizard is open */}
        {!showWizard && (
          <div className="px-5 py-4 border-t border-gray-100 flex-shrink-0">
            <button
              onClick={() => setShowWizard(true)}
              className="w-full py-2 px-4 bg-blue-600 hover:bg-blue-700 text-white text-sm font-medium rounded-lg transition-colors"
            >
              + New Appointment
            </button>
          </div>
        )}
      </div>
    </>
  )
}
