import {
  collection,
  query,
  where,
  getDocs,
  addDoc,
  Timestamp,
} from "firebase/firestore"
import { db } from "../firebase/config"

export interface ServiceTicket {
  id: string
  appointmentId: string
  clientId: string
  clientName: string
  vehicleId: string
  serviceType: string
  customServiceDescription: string
  quotedPrice: number
  estimatedDuration: number
  billableAmount: number
  taxGST: number
  taxQST: number
  nonBillableAmount: number
  sendConfirmation: boolean
  status: "draft" | "confirmed" | "completed"
  createdAt: Date
  updatedAt: Date
}

export type NewTicketData = Omit<ServiceTicket, "id" | "createdAt" | "updatedAt">

export async function createTicket(data: NewTicketData): Promise<ServiceTicket> {
  if (!db) throw new Error("Firestore not initialized")

  const now = Timestamp.now()
  const docRef = await addDoc(collection(db, "serviceTickets"), {
    ...data,
    createdAt: now,
    updatedAt: now,
  })

  return {
    id: docRef.id,
    ...data,
    createdAt: now.toDate(),
    updatedAt: now.toDate(),
  }
}

export async function getTicketByAppointment(appointmentId: string): Promise<ServiceTicket | null> {
  if (!db) return null

  const snap = await getDocs(
    query(
      collection(db, "serviceTickets"),
      where("appointmentId", "==", appointmentId)
    )
  )

  if (snap.empty) return null

  const d = snap.docs[0]
  const data = d.data()
  return {
    id: d.id,
    appointmentId: data.appointmentId,
    clientId: data.clientId,
    clientName: data.clientName,
    vehicleId: data.vehicleId,
    serviceType: data.serviceType,
    customServiceDescription: data.customServiceDescription,
    quotedPrice: data.quotedPrice,
    estimatedDuration: data.estimatedDuration,
    billableAmount: data.billableAmount,
    taxGST: data.taxGST,
    taxQST: data.taxQST,
    nonBillableAmount: data.nonBillableAmount,
    sendConfirmation: data.sendConfirmation,
    status: data.status,
    createdAt: (data.createdAt as Timestamp).toDate(),
    updatedAt: (data.updatedAt as Timestamp).toDate(),
  }
}
