import React from "react"
import { useDraggable } from "@dnd-kit/core"
import { CSS } from "@dnd-kit/utilities"
import { Appointment, AppointmentStatus } from "../../../hooks/useAppointments"

interface AppointmentChipProps {
  appointment: Appointment
  statusColors: Record<AppointmentStatus, string>
}

export default function AppointmentChip({ appointment, statusColors }: AppointmentChipProps) {
  const { attributes, listeners, setNodeRef, transform, isDragging } = useDraggable({
    id: appointment.id,
    data: { appointment },
  })

  const style = {
    transform: CSS.Translate.toString(transform),
    opacity: isDragging ? 0.4 : 1,
    cursor: isDragging ? "grabbing" : "grab",
  }

  const shortName = appointment.clientName.split(" ")[0]

  return (
    <div
      ref={setNodeRef}
      style={style}
      {...listeners}
      {...attributes}
      className={`text-xs px-1.5 py-0.5 rounded truncate ${statusColors[appointment.status]}`}
      title={`${appointment.timeSlot} — ${appointment.clientName}`}
    >
      {appointment.timeSlot} {shortName}
    </div>
  )
}
