import { useState, useEffect } from "react"
import { doc, onSnapshot } from "firebase/firestore"
import { db } from "../firebase/config"

export interface ServiceItem {
  id: string
  label: string
  isActive: boolean
  order: number
}

export interface TaxSettings {
  GST: number
  QST: number
}

interface SettingsResult {
  services: ServiceItem[]
  taxes: TaxSettings
  loading: boolean
}

const DEFAULT_TAXES: TaxSettings = { GST: 5, QST: 9.975 }

export function useSettings(): SettingsResult {
  const [services, setServices] = useState<ServiceItem[]>([])
  const [taxes, setTaxes] = useState<TaxSettings>(DEFAULT_TAXES)
  const [loading, setLoading] = useState(true)

  useEffect(() => {
    if (!db) {
      setLoading(false)
      return
    }

    let servicesLoaded = false
    let taxesLoaded = false

    const checkDone = () => {
      if (servicesLoaded && taxesLoaded) setLoading(false)
    }

    const unsubServices = onSnapshot(doc(db, "settings", "services"), snap => {
      const data = snap.data()
      if (data?.list) {
        const list = (data.list as ServiceItem[])
          .filter(s => s.isActive)
          .sort((a, b) => a.order - b.order)
        setServices(list)
      }
      servicesLoaded = true
      checkDone()
    })

    const unsubTaxes = onSnapshot(doc(db, "settings", "taxes"), snap => {
      const data = snap.data()
      if (data) {
        setTaxes({ GST: data.GST ?? 5, QST: data.QST ?? 9.975 })
      }
      taxesLoaded = true
      checkDone()
    })

    return () => {
      unsubServices()
      unsubTaxes()
    }
  }, [])

  return { services, taxes, loading }
}
