import React, { useReducer } from "react"
import { Client } from "../../../hooks/useClients"
import ClientSearch from "../Clients/ClientSearch"
import ClientForm from "../Clients/ClientForm"
import VehicleSelector from "../Clients/VehicleSelector"
import ServiceTicketForm from "./ServiceTicketForm"

type Step = "search" | "new-client" | "vehicle" | "service"

interface WizardState {
  step: Step
  client: Client | null
  vehicleId: string | null
  isDirty: boolean
}

type WizardAction =
  | { type: "SELECT_CLIENT"; client: Client }
  | { type: "GO_NEW_CLIENT" }
  | { type: "CLIENT_CREATED"; client: Client }
  | { type: "CLIENT_UPDATED"; client: Client }
  | { type: "SELECT_VEHICLE"; vehicleId: string }
  | { type: "GO_SERVICE" }
  | { type: "GO_BACK" }
  | { type: "SET_DIRTY" }

function reducer(state: WizardState, action: WizardAction): WizardState {
  switch (action.type) {
    case "SELECT_CLIENT":
      return { ...state, client: action.client, step: "vehicle", isDirty: true }
    case "GO_NEW_CLIENT":
      return { ...state, step: "new-client", isDirty: true }
    case "CLIENT_CREATED":
      return { ...state, client: action.client, step: "vehicle", isDirty: true }
    case "CLIENT_UPDATED":
      return { ...state, client: action.client }
    case "SELECT_VEHICLE":
      return { ...state, vehicleId: action.vehicleId }
    case "GO_SERVICE":
      return { ...state, step: "service" }
    case "GO_BACK":
      if (state.step === "vehicle") return { ...state, step: "search" }
      if (state.step === "new-client") return { ...state, step: "search" }
      if (state.step === "service") return { ...state, step: "vehicle" }
      return state
    case "SET_DIRTY":
      return { ...state, isDirty: true }
    default:
      return state
  }
}

const STEP_LABELS: { id: Step | "service"; label: string }[] = [
  { id: "search", label: "Client" },
  { id: "vehicle", label: "Vehicle" },
  { id: "service", label: "Service" },
]

function StepIndicator({ current }: { current: Step }) {
  const order: Step[] = ["search", "vehicle", "service"]
  const currentIndex = order.indexOf(current === "new-client" ? "search" : current)

  return (
    <div className="flex items-center gap-2 mb-5">
      {STEP_LABELS.map((s, i) => {
        const done = i < currentIndex
        const active = i === currentIndex
        return (
          <React.Fragment key={s.id}>
            <div className="flex items-center gap-1.5">
              <div
                className={`w-6 h-6 rounded-full text-xs font-bold flex items-center justify-center ${
                  done
                    ? "bg-green-500 text-white"
                    : active
                    ? "bg-blue-600 text-white"
                    : "bg-gray-200 text-gray-500"
                }`}
              >
                {done ? "✓" : i + 1}
              </div>
              <span
                className={`text-xs font-medium ${
                  active ? "text-blue-600" : done ? "text-green-600" : "text-gray-400"
                }`}
              >
                {s.label}
              </span>
            </div>
            {i < STEP_LABELS.length - 1 && (
              <div className={`flex-1 h-px ${done ? "bg-green-300" : "bg-gray-200"}`} />
            )}
          </React.Fragment>
        )
      })}
    </div>
  )
}

interface AppointmentWizardProps {
  date: Date
  onDone: () => void
  onCancel: () => void
}

export default function AppointmentWizard({
  date,
  onDone,
  onCancel,
}: AppointmentWizardProps) {
  const [state, dispatch] = useReducer(reducer, {
    step: "search",
    client: null,
    vehicleId: null,
    isDirty: false,
  })

  function handleCancel() {
    if (state.isDirty) {
      if (!window.confirm("Discard this appointment? Any entered data will be lost.")) return
    }
    onCancel()
  }

  return (
    <div className="flex flex-col h-full">
      {/* Wizard header */}
      <div className="flex items-center justify-between mb-4">
        <h3 className="text-sm font-semibold text-gray-800">New Appointment</h3>
        <button
          onClick={handleCancel}
          className="text-gray-400 hover:text-gray-600 text-sm transition-colors"
        >
          Cancel
        </button>
      </div>

      <StepIndicator current={state.step} />

      {/* Step content */}
      <div className="flex-1 overflow-y-auto">
        {(state.step === "search") && (
          <ClientSearch
            onSelect={client => dispatch({ type: "SELECT_CLIENT", client })}
            onCreateNew={() => dispatch({ type: "GO_NEW_CLIENT" })}
          />
        )}

        {state.step === "new-client" && (
          <ClientForm
            onSaved={client => dispatch({ type: "CLIENT_CREATED", client })}
            onBack={() => dispatch({ type: "GO_BACK" })}
          />
        )}

        {state.step === "vehicle" && state.client && (
          <VehicleSelector
            client={state.client}
            onClientUpdated={client => dispatch({ type: "CLIENT_UPDATED", client })}
            selectedVehicleId={state.vehicleId}
            onSelect={vehicleId => dispatch({ type: "SELECT_VEHICLE", vehicleId })}
            onContinue={() => dispatch({ type: "GO_SERVICE" })}
            onBack={() => dispatch({ type: "GO_BACK" })}
          />
        )}

        {state.step === "service" && state.client && state.vehicleId && (
          <ServiceTicketForm
            date={date}
            client={state.client}
            vehicleId={state.vehicleId}
            onSaved={onDone}
            onBack={() => dispatch({ type: "GO_BACK" })}
          />
        )}
      </div>
    </div>
  )
}
