import React, { useState } from "react"
import { Client, Vehicle, NewVehicleData, addVehicle } from "../../../hooks/useClients"

interface VehicleSelectorProps {
  client: Client
  onClientUpdated: (updated: Client) => void
  selectedVehicleId: string | null
  onSelect: (vehicleId: string) => void
  onContinue: () => void
  onBack: () => void
}

const CURRENT_YEAR = new Date().getFullYear()

interface VehicleFormState {
  make: string
  model: string
  year: string
  color: string
  notes: string
}

interface VehicleFormErrors {
  make?: string
  model?: string
  year?: string
  notes?: string
}

function validateVehicle(f: VehicleFormState): VehicleFormErrors {
  const errors: VehicleFormErrors = {}
  if (!f.make.trim()) errors.make = "Make is required"
  if (!f.model.trim()) errors.model = "Model is required"
  const y = parseInt(f.year, 10)
  if (!f.year || isNaN(y) || y < 1950 || y > CURRENT_YEAR + 1)
    errors.year = `Year must be between 1950 and ${CURRENT_YEAR + 1}`
  if (f.notes.length > 200) errors.notes = "Max 200 characters"
  return errors
}

export default function VehicleSelector({
  client,
  onClientUpdated,
  selectedVehicleId,
  onSelect,
  onContinue,
  onBack,
}: VehicleSelectorProps) {
  const [showForm, setShowForm] = useState(client.vehicles.length === 0)
  const [form, setForm] = useState<VehicleFormState>({
    make: "", model: "", year: "", color: "", notes: "",
  })
  const [formErrors, setFormErrors] = useState<VehicleFormErrors>({})
  const [saving, setSaving] = useState(false)

  function set(field: keyof VehicleFormState, value: string) {
    setForm(prev => ({ ...prev, [field]: value }))
  }

  async function handleAddVehicle() {
    const errs = validateVehicle(form)
    setFormErrors(errs)
    if (Object.keys(errs).length > 0) return

    setSaving(true)
    try {
      const vehicleData: NewVehicleData = {
        make: form.make.trim(),
        model: form.model.trim(),
        year: parseInt(form.year, 10),
        color: form.color.trim(),
        notes: form.notes.trim(),
      }
      const newVehicle = await addVehicle(client.id, vehicleData)
      const updated: Client = {
        ...client,
        vehicles: [...client.vehicles, newVehicle],
      }
      onClientUpdated(updated)
      onSelect(newVehicle.vehicleId)
      setShowForm(false)
      setForm({ make: "", model: "", year: "", color: "", notes: "" })
      setFormErrors({})
    } catch {
      setFormErrors({ make: "Failed to add vehicle. Please try again." })
    } finally {
      setSaving(false)
    }
  }

  return (
    <div className="flex flex-col gap-4">
      {/* Vehicle list */}
      {client.vehicles.length > 0 && (
        <div className="flex flex-col gap-2">
          {client.vehicles.map((v: Vehicle) => (
            <label
              key={v.vehicleId}
              className={`flex items-center gap-3 p-3 rounded-lg border cursor-pointer transition-colors ${
                selectedVehicleId === v.vehicleId
                  ? "border-blue-500 bg-blue-50"
                  : "border-gray-200 hover:border-gray-300"
              }`}
            >
              <input
                type="radio"
                name="vehicle"
                value={v.vehicleId}
                checked={selectedVehicleId === v.vehicleId}
                onChange={() => onSelect(v.vehicleId)}
                className="accent-blue-600"
              />
              <span className="text-sm text-gray-800">
                {v.year} {v.make} {v.model}
                {v.color ? ` — ${v.color}` : ""}
              </span>
            </label>
          ))}
        </div>
      )}

      {/* Add vehicle toggle */}
      {!showForm ? (
        <button
          onClick={() => setShowForm(true)}
          className="text-sm text-blue-600 hover:text-blue-700 font-medium text-left transition-colors"
        >
          + Add Vehicle
        </button>
      ) : (
        <div className="border border-gray-200 rounded-lg p-4 flex flex-col gap-3">
          <p className="text-xs font-semibold text-gray-600 uppercase tracking-wide">New Vehicle</p>

          <div className="grid grid-cols-2 gap-3">
            <div>
              <label htmlFor="vs-make" className="block text-xs font-medium text-gray-700 mb-1">
                Make <span className="text-red-500">*</span>
              </label>
              <input
                id="vs-make"
                value={form.make}
                onChange={e => set("make", e.target.value)}
                className={`w-full border rounded-lg px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${formErrors.make ? "border-red-400" : "border-gray-300"}`}
                placeholder="Toyota"
              />
              {formErrors.make && <p className="text-xs text-red-500 mt-0.5">{formErrors.make}</p>}
            </div>

            <div>
              <label htmlFor="vs-model" className="block text-xs font-medium text-gray-700 mb-1">
                Model <span className="text-red-500">*</span>
              </label>
              <input
                id="vs-model"
                value={form.model}
                onChange={e => set("model", e.target.value)}
                className={`w-full border rounded-lg px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${formErrors.model ? "border-red-400" : "border-gray-300"}`}
                placeholder="Camry"
              />
              {formErrors.model && <p className="text-xs text-red-500 mt-0.5">{formErrors.model}</p>}
            </div>

            <div>
              <label htmlFor="vs-year" className="block text-xs font-medium text-gray-700 mb-1">
                Year <span className="text-red-500">*</span>
              </label>
              <input
                id="vs-year"
                type="number"
                value={form.year}
                onChange={e => set("year", e.target.value)}
                min={1950}
                max={CURRENT_YEAR + 1}
                className={`w-full border rounded-lg px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${formErrors.year ? "border-red-400" : "border-gray-300"}`}
                placeholder={String(CURRENT_YEAR)}
              />
              {formErrors.year && <p className="text-xs text-red-500 mt-0.5">{formErrors.year}</p>}
            </div>

            <div>
              <label htmlFor="vs-color" className="block text-xs font-medium text-gray-700 mb-1">Color</label>
              <input
                id="vs-color"
                value={form.color}
                onChange={e => set("color", e.target.value)}
                className="w-full border border-gray-300 rounded-lg px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="Silver"
              />
            </div>
          </div>

          <div>
            <label htmlFor="vs-notes" className="block text-xs font-medium text-gray-700 mb-1">
              Notes / Observations
              <span className="ml-1 text-gray-400 font-normal">({form.notes.length}/200)</span>
            </label>
            <textarea
              id="vs-notes"
              value={form.notes}
              onChange={e => set("notes", e.target.value)}
              maxLength={200}
              rows={2}
              className={`w-full border rounded-lg px-2 py-1.5 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 resize-none ${formErrors.notes ? "border-red-400" : "border-gray-300"}`}
              placeholder="Any known issues, modifications, etc."
            />
            {formErrors.notes && <p className="text-xs text-red-500 mt-0.5">{formErrors.notes}</p>}
          </div>

          <div className="flex gap-2">
            <button
              onClick={() => { setShowForm(false); setFormErrors({}) }}
              className="flex-1 py-1.5 border border-gray-300 text-gray-700 text-sm rounded-lg hover:bg-gray-50 transition-colors"
            >
              Cancel
            </button>
            <button
              onClick={handleAddVehicle}
              disabled={saving}
              className="flex-1 py-1.5 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-300 text-white text-sm rounded-lg transition-colors"
            >
              {saving ? "Saving…" : "Confirm"}
            </button>
          </div>
        </div>
      )}

      {/* Navigation */}
      <div className="flex gap-3 pt-2">
        <button
          onClick={onBack}
          className="flex-1 py-2 px-4 border border-gray-300 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-50 transition-colors"
        >
          ← Back
        </button>
        <button
          onClick={onContinue}
          disabled={!selectedVehicleId}
          className="flex-1 py-2 px-4 bg-blue-600 hover:bg-blue-700 disabled:bg-gray-200 disabled:text-gray-400 text-white text-sm font-medium rounded-lg transition-colors"
        >
          Continue with selected vehicle →
        </button>
      </div>
    </div>
  )
}
