import React, { useState, useEffect } from "react"
import { addDoc, collection, Timestamp } from "firebase/firestore"
import { db } from "../../../firebase/config"
import { Client } from "../../../hooks/useClients"
import { createTicket } from "../../../hooks/useServiceTickets"
import { useSettings } from "../../../hooks/useSettings"
import { useToast } from "../../../context/ToastContext"

const DURATION_OPTIONS = [30, 60, 90, 120, 180, 240]

function roundToNearestHalfHour(date: Date): string {
  const h = date.getHours()
  const m = date.getMinutes() < 30 ? 0 : 30
  return `${String(h).padStart(2, "0")}:${String(m).padStart(2, "0")}`
}

function generateTimeSlots(): string[] {
  const slots: string[] = []
  for (let h = 7; h <= 18; h++) {
    slots.push(`${String(h).padStart(2, "0")}:00`)
    if (h < 18) slots.push(`${String(h).padStart(2, "0")}:30`)
  }
  return slots
}

interface ServiceTicketFormProps {
  date: Date
  client: Client
  vehicleId: string
  onSaved: () => void
  onBack: () => void
}

export default function ServiceTicketForm({
  date,
  client,
  vehicleId,
  onSaved,
  onBack,
}: ServiceTicketFormProps) {
  const { services, taxes, loading: settingsLoading } = useSettings()
  const { showToast } = useToast()

  const timeSlots = generateTimeSlots()
  const [timeSlot, setTimeSlot] = useState(roundToNearestHalfHour(new Date()))
  const [serviceType, setServiceType] = useState("")
  const [customDescription, setCustomDescription] = useState("")
  const [durationPreset, setDurationPreset] = useState<number | "custom">(60)
  const [customDuration, setCustomDuration] = useState("")
  const [quotedPrice, setQuotedPrice] = useState("")
  const [billableEnabled, setBillableEnabled] = useState(false)
  const [billableAmount, setBillableAmount] = useState("")
  const [nonBillableEnabled, setNonBillableEnabled] = useState(false)
  const [nonBillableAmount, setNonBillableAmount] = useState("")
  const [sendConfirmation, setSendConfirmation] = useState(false)
  const [saving, setSaving] = useState(false)
  const [errors, setErrors] = useState<Record<string, string>>({})

  const billable = parseFloat(billableAmount) || 0
  const gstAmount = billable * (taxes.GST / 100)
  const qstAmount = billable * (taxes.QST / 100)
  const total = billable + gstAmount + qstAmount

  const estimatedDuration =
    durationPreset === "custom" ? parseInt(customDuration, 10) || 0 : durationPreset

  // Set default service once settings load
  useEffect(() => {
    if (services.length > 0 && !serviceType) {
      setServiceType(services[0].id)
    }
  }, [services, serviceType])

  function validate(): boolean {
    const errs: Record<string, string> = {}
    if (!serviceType) errs.service = "Select a service"
    if (serviceType === "custom" && !customDescription.trim())
      errs.customDescription = "Description is required for custom service"
    if (customDescription.length > 500)
      errs.customDescription = "Max 500 characters"
    if (durationPreset === "custom" && (!customDuration || isNaN(parseInt(customDuration, 10))))
      errs.duration = "Enter a valid duration in minutes"
    setErrors(errs)
    return Object.keys(errs).length === 0
  }

  async function handleSave() {
    if (!validate() || !db) return
    setSaving(true)

    try {
      const apptDate = new Date(date)
      const [h, m] = timeSlot.split(":").map(Number)
      apptDate.setHours(h, m, 0, 0)

      // 1. Create appointment
      const now = Timestamp.now()
      const apptRef = await addDoc(collection(db, "appointments"), {
        clientId: client.id,
        clientName: client.name,
        date: Timestamp.fromDate(apptDate),
        timeSlot,
        status: "scheduled",
        serviceType: serviceType === "custom" ? "custom" : serviceType,
        estimatedDuration,
        notes: serviceType === "custom" ? customDescription : "",
        clientConfirmedAt: null,
        clientCancelledAt: null,
        createdAt: now,
        updatedAt: now,
      })

      // 2. Create service ticket
      await createTicket({
        appointmentId: apptRef.id,
        clientId: client.id,
        clientName: client.name,
        vehicleId,
        serviceType: serviceType === "custom" ? "custom" : serviceType,
        customServiceDescription: serviceType === "custom" ? customDescription : "",
        quotedPrice: parseFloat(quotedPrice) || 0,
        estimatedDuration,
        billableAmount: billableEnabled ? billable : 0,
        taxGST: billableEnabled ? parseFloat(gstAmount.toFixed(2)) : 0,
        taxQST: billableEnabled ? parseFloat(qstAmount.toFixed(2)) : 0,
        nonBillableAmount: nonBillableEnabled ? parseFloat(nonBillableAmount) || 0 : 0,
        sendConfirmation,
        status: "draft",
      })

      showToast("Appointment created successfully", "success")
      onSaved()
    } catch {
      showToast("Failed to save appointment. Please try again.", "error")
    } finally {
      setSaving(false)
    }
  }

  if (settingsLoading) {
    return (
      <div className="flex items-center justify-center py-8">
        <div className="w-6 h-6 border-4 border-blue-500 border-t-transparent rounded-full animate-spin" />
      </div>
    )
  }

  return (
    <div className="flex flex-col gap-5">

      {/* Appointment Details */}
      <section>
        <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3">
          Appointment Details
        </h3>
        <div>
          <label htmlFor="st-timeslot" className="block text-xs font-medium text-gray-700 mb-1">
            Time
          </label>
          <select
            id="st-timeslot"
            value={timeSlot}
            onChange={e => setTimeSlot(e.target.value)}
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            {timeSlots.map(t => (
              <option key={t} value={t}>{t}</option>
            ))}
          </select>
        </div>
      </section>

      {/* Service */}
      <section>
        <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3">
          Service
        </h3>
        {errors.service && <p className="text-xs text-red-500 mb-2">{errors.service}</p>}

        <div className="flex flex-col gap-2">
          {services.map(s => (
            <label key={s.id} className="flex items-center gap-2 cursor-pointer">
              <input
                type="radio"
                name="service"
                value={s.id}
                checked={serviceType === s.id}
                onChange={() => setServiceType(s.id)}
                className="accent-blue-600"
              />
              <span className="text-sm text-gray-800">{s.label}</span>
            </label>
          ))}
          <label className="flex items-center gap-2 cursor-pointer">
            <input
              type="radio"
              name="service"
              value="custom"
              checked={serviceType === "custom"}
              onChange={() => setServiceType("custom")}
              className="accent-blue-600"
            />
            <span className="text-sm text-gray-800">Other / Custom Description</span>
          </label>
        </div>

        {serviceType === "custom" && (
          <div className="mt-2">
            <textarea
              value={customDescription}
              onChange={e => setCustomDescription(e.target.value)}
              maxLength={500}
              rows={3}
              placeholder="Describe the service…"
              className={`w-full border rounded-lg px-3 py-2 text-sm resize-none focus:outline-none focus:ring-2 focus:ring-blue-500 ${errors.customDescription ? "border-red-400" : "border-gray-300"}`}
            />
            <div className="flex justify-between mt-0.5">
              {errors.customDescription
                ? <p className="text-xs text-red-500">{errors.customDescription}</p>
                : <span />}
              <span className="text-xs text-gray-400">{customDescription.length}/500</span>
            </div>
          </div>
        )}

        {/* Duration */}
        <div className="mt-3">
          <label htmlFor="st-duration" className="block text-xs font-medium text-gray-700 mb-1">
            Estimated Duration
          </label>
          <select
            id="st-duration"
            value={durationPreset}
            onChange={e => {
              const v = e.target.value
              setDurationPreset(v === "custom" ? "custom" : parseInt(v, 10))
            }}
            className="w-full border border-gray-300 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
          >
            {DURATION_OPTIONS.map(d => (
              <option key={d} value={d}>{d} min</option>
            ))}
            <option value="custom">Custom (minutes)</option>
          </select>
          {durationPreset === "custom" && (
            <input
              type="number"
              value={customDuration}
              onChange={e => setCustomDuration(e.target.value)}
              placeholder="Minutes"
              className={`w-full mt-2 border rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 ${errors.duration ? "border-red-400" : "border-gray-300"}`}
            />
          )}
          {errors.duration && <p className="text-xs text-red-500 mt-1">{errors.duration}</p>}
        </div>

        {/* Quoted price */}
        <div className="mt-3">
          <label htmlFor="st-quoted" className="block text-xs font-medium text-gray-700 mb-1">
            Quoted Price
          </label>
          <div className="relative">
            <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-sm">$</span>
            <input
              id="st-quoted"
              type="number"
              min={0}
              step={0.01}
              value={quotedPrice}
              onChange={e => setQuotedPrice(e.target.value)}
              className="w-full border border-gray-300 rounded-lg pl-7 pr-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
              placeholder="0.00"
            />
          </div>
        </div>
      </section>

      {/* Payment */}
      <section>
        <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3">
          Payment
        </h3>

        {/* Billable toggle */}
        <label className="flex items-center gap-2 mb-2 cursor-pointer">
          <input
            type="checkbox"
            checked={billableEnabled}
            onChange={e => setBillableEnabled(e.target.checked)}
            className="accent-blue-600"
          />
          <span className="text-sm font-medium text-gray-700">Billable Payment</span>
        </label>

        {billableEnabled && (
          <div className="ml-5 mb-3 flex flex-col gap-2">
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-sm">$</span>
              <input
                type="number"
                min={0}
                step={0.01}
                value={billableAmount}
                onChange={e => setBillableAmount(e.target.value)}
                className="w-full border border-gray-300 rounded-lg pl-7 pr-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="0.00"
              />
            </div>
            <div className="bg-gray-50 rounded-lg p-3 text-xs font-mono space-y-1 text-gray-600">
              <div className="flex justify-between">
                <span>GST ({taxes.GST}%):</span>
                <span>${gstAmount.toFixed(2)}</span>
              </div>
              <div className="flex justify-between">
                <span>QST ({taxes.QST}%):</span>
                <span>${qstAmount.toFixed(2)}</span>
              </div>
              <div className="flex justify-between border-t border-gray-200 pt-1 font-bold text-gray-800">
                <span>Total:</span>
                <span>${total.toFixed(2)}</span>
              </div>
            </div>
          </div>
        )}

        {/* Non-billable toggle */}
        <label className="flex items-center gap-2 cursor-pointer">
          <input
            type="checkbox"
            checked={nonBillableEnabled}
            onChange={e => setNonBillableEnabled(e.target.checked)}
            className="accent-blue-600"
          />
          <span className="text-sm font-medium text-gray-700">Non-Billable Payment</span>
        </label>

        {nonBillableEnabled && (
          <div className="ml-5 mt-2">
            <div className="relative">
              <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-sm">$</span>
              <input
                type="number"
                min={0}
                step={0.01}
                value={nonBillableAmount}
                onChange={e => setNonBillableAmount(e.target.value)}
                className="w-full border border-gray-300 rounded-lg pl-7 pr-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
                placeholder="0.00"
              />
            </div>
          </div>
        )}
      </section>

      {/* Notifications */}
      <section>
        <h3 className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-3">
          Notifications
        </h3>
        <div className="flex items-center gap-4">
          <span className="text-sm text-gray-700">Send email confirmation to client:</span>
          <label className="flex items-center gap-1.5 cursor-pointer">
            <input
              type="radio"
              name="confirm"
              checked={sendConfirmation}
              onChange={() => setSendConfirmation(true)}
              className="accent-blue-600"
            />
            <span className="text-sm">Yes</span>
          </label>
          <label className="flex items-center gap-1.5 cursor-pointer">
            <input
              type="radio"
              name="confirm"
              checked={!sendConfirmation}
              onChange={() => setSendConfirmation(false)}
              className="accent-blue-600"
            />
            <span className="text-sm">No</span>
          </label>
        </div>

        {sendConfirmation && !client.email && (
          <p className="mt-2 text-xs text-red-600 bg-red-50 rounded-lg px-3 py-2">
            This client has no email address. Add one in their profile to send confirmation.
          </p>
        )}
        {sendConfirmation && client.email && (
          <p className="mt-2 text-xs text-gray-500">
            Confirmation will be sent to: <span className="font-medium text-gray-700">{client.email}</span>
          </p>
        )}
        <p className="mt-2 text-xs text-gray-400 italic">
          Email integration coming soon — selection is saved for future use.
        </p>
      </section>

      {/* Actions */}
      <div className="flex gap-3 pt-2">
        <button
          onClick={onBack}
          className="flex-1 py-2 px-4 border border-gray-300 text-gray-700 text-sm font-medium rounded-lg hover:bg-gray-50 transition-colors"
        >
          ← Back
        </button>
        <button
          onClick={handleSave}
          disabled={saving}
          className="flex-1 py-2 px-4 bg-blue-600 hover:bg-blue-700 disabled:bg-blue-300 text-white text-sm font-medium rounded-lg transition-colors"
        >
          {saving ? "Saving…" : "Save Appointment"}
        </button>
      </div>
    </div>
  )
}
